bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const e=process.env;
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try {
 const old=await db.query("SELECT listing_id FROM videobot_post_receipts WHERE paid_message_id=$1",[4691]);
 if(old.rowCount!==1)process.exitCode=61;
 else {
  const id=old.rows[0].listing_id;
  const receipts=await db.query("SELECT revision,status,free_message_ids,paid_message_id,topic_id FROM videobot_post_receipts WHERE listing_id=$1 ORDER BY revision",[id]);
  const listing=await db.query("SELECT revision,status,price_stars,thumbnail_file_id,sample_file_id,paid_video_file_id,rights_verified,adult_consent_verified,fee_terms_accepted_at FROM videobot_listings WHERE listing_id=$1",[id]);
  const ledger=await db.query("SELECT COUNT(*)::int AS n FROM videobot_stars_ledger WHERE listing_id=$1 AND kind=$2",[id,'paid']);
  if(listing.rowCount!==1)process.exitCode=62;
  else if(receipts.rowCount<2)process.exitCode=63;
  else if(receipts.rows.some(x=>x.status!=='sent'||!x.paid_message_id||!Array.isArray(x.free_message_ids)||x.free_message_ids.length!==2))process.exitCode=64;
  else if(Number(ledger.rows[0].n)>0)process.exitCode=65;
  else if(!listing.rows[0].paid_video_file_id||Number(listing.rows[0].price_stars)!==10)process.exitCode=66;
  else if(!listing.rows[0].rights_verified||!listing.rows[0].adult_consent_verified||!listing.rows[0].fee_terms_accepted_at)process.exitCode=67;
  else {console.log('REPOST_PREFLIGHT_NO_RECORDED_BUYERS=PASS');console.log('OLD_RECEIPTS='+receipts.rowCount);}
 }
} catch(error) {
 console.error('REPOST_PREFLIGHT_DB_ERROR_CODE='+String(error?.code??'other').slice(0,12));
 process.exitCode=79;
} finally {await db.end()}
JS
